type UpdateUserRow struct {
	ID           uuid.UUID
	WorkspaceID  uuid.UUID
	UserID       uuid.UUID
	UserName     string
	ExternalID   *string
	Active       bool
	Profile      []byte
	PreviousRole string
	Version      int64
	CreatedAt    time.Time
	UpdatedAt    time.Time
}

func (q *Queries) UpdateUser(ctx context.Context, arg UpdateUserParams) (UpdateUserRow, error) {
	row := q.db.QueryRow(ctx, updateUser,
		arg.UserName,
		arg.ExternalID,
		arg.Active,
		arg.Profile,
		arg.PreviousRole,
		arg.Deleted,
		arg.WorkspaceID,
		arg.ID,
		arg.ExpectedVersion,
	)
	var i UpdateUserRow
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.UserID,
		&i.UserName,
		&i.ExternalID,
		&i.Active,
		&i.Profile,
		&i.PreviousRole,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
